    // ── SESSION ──
    private string? _maTruongBo;
    private string? _selectedNamHoc;
    private string? _selectedCapHoc;

    // ── FILTER ──
    private List<KhoiHoc_DTO>  _khoiList   = new();
    private List<LopHoc_DTO>   _allLopList = new();
    private List<LopHoc_DTO>   _lopFiltered = new();
    private int    _selKhoiId  = 0;
    private string _selMaLop   = "";
    private string _selTenLop  = "";

    // ── TAB ──
    private string _activeTab = "diem";

    // ── DATA ──
    private List<MonHocDTO>               _monHocList = new();
    private List<ThongKeDiemMonHocDTO>    _diemList   = new();
    private List<ThongKeDanhGiaDinhKyDTO> _dgList     = new();
    private List<ThongKeXepLoaiNangLucDTO>   _nlList  = new();
    private List<ThongKeXepLoaiPhamChatDTO>  _pcList  = new();

    private bool _isLoading = false;

    // ── KHEN THƯỞNG ──
    private ScnKetQuaKhenThuongDTO _khenModel     = new();
    private bool                   _isKhenSaving  = false;
    private bool                   _quillInitialized = false;
    private int                    _selLopId      = 0; // IdLopBo (int)

    // ── TOAST ──
    private string _toastMsg  = "";
    private string _toastCss  = "";
    private string _toastIcon = "";
    private System.Threading.CancellationTokenSource? _toastCts;

    // ── LIFECYCLE ──
    protected override async Task OnInitializedAsync()
    {
        _maTruongBo     = await BrowserStorageService.GetMaTruongBoAsync(JS);
        _selectedNamHoc = await BrowserStorageService.GetItem(JS, "selectedNamHoc");
        _selectedCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevel");

        // Load khối, lớp, môn học song song
        var taskKhoi   = TruongService.hGetDanhSachKhoi(_maTruongBo ?? "", _selectedCapHoc ?? "1");
        var taskLop    = TruongService.hGetDanhSachLop(_maTruongBo ?? "", _selectedCapHoc ?? "1", _selectedNamHoc ?? "");
        var taskMonHoc = DaoTaoService.hGetMonHoc(_maTruongBo ?? "");

        await Task.WhenAll(taskKhoi, taskLop, taskMonHoc);

        _khoiList   = taskKhoi.Result;
        _allLopList = taskLop.Result;
        _monHocList = taskMonHoc.Result;

        // Auto-select khối đầu tiên
        if (_khoiList.Any())
        {
            _selKhoiId   = _khoiList[0].MaKhoi;
            _lopFiltered = _allLopList.Where(l => l.MaKhoi == _selKhoiId).ToList();
        }
        else _lopFiltered = _allLopList.ToList();

        // Auto-select lớp đầu tiên
        if (_lopFiltered.Any())
        {
            _selMaLop  = _lopFiltered[0].MaLopBo;
            _selTenLop = _lopFiltered[0].TenLop;
            _selLopId  = _lopFiltered[0].IdLopBo;
            await LoadTabData();
        }
    }

    // ── FILTER EVENTS ──
    private async Task OnKhoiChanged(ChangeEventArgs e)
    {
        _selKhoiId = int.TryParse(e.Value?.ToString(), out var kv) ? kv : 0;
        _lopFiltered = _selKhoiId == 0
            ? _allLopList.ToList()
            : _allLopList.Where(l => l.MaKhoi == _selKhoiId).ToList();

        if (_lopFiltered.Any())
        {
            _selMaLop  = _lopFiltered[0].MaLopBo;
            _selTenLop = _lopFiltered[0].TenLop;
            _selLopId  = _lopFiltered[0].IdLopBo;
        }
        else { _selMaLop = ""; _selTenLop = ""; _selLopId = 0; }

        ClearData();
        if (!string.IsNullOrEmpty(_selMaLop))
            await LoadTabData();
    }

    private async Task OnLopChanged(ChangeEventArgs e)
    {
        _selMaLop = e.Value?.ToString() ?? "";
        var lop   = _lopFiltered.FirstOrDefault(l => l.MaLopBo == _selMaLop);
        _selTenLop = lop?.TenLop ?? "";
        _selLopId  = lop?.IdLopBo ?? 0;
        ClearData();
        if (!string.IsNullOrEmpty(_selMaLop))
            await LoadTabData();
    }

    private void SetTab(string tab)
    {
        // Khi rời tab khen, reset quill để init lại ở tab tiếp theo
        if (_activeTab == "khen" && tab != "khen")
            _quillInitialized = false;
        _activeTab = tab;
        StateHasChanged();
    }

    // ── LIFECYCLE: AFTER RENDER (Quill init) ──
    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (_activeTab == "khen" && !_quillInitialized && !string.IsNullOrEmpty(_selMaLop))
        {
            _quillInitialized = true;
            try
            {
                await JS.InvokeVoidAsync("scnKhen.init",
                    "khen-quill-editor",
                    _khenModel?.NoiDungKhenThuong ?? "");
            }
            catch { /* Quill chưa load hoặc element chưa mount */ }
        }
    }

    // ── LOAD DATA (luôn load cả 4 tab cùng lúc) ──
    private async Task LoadTabData()
    {
        if (string.IsNullOrEmpty(_selMaLop)) return;

        _isLoading = true; StateHasChanged();
        try
        {
            var t1 = TruongService.hGetThongKeDiemDanhGiaTheoLop(_selMaLop, _selectedNamHoc ?? "");
            var t2 = TruongService.hGetThongKeDanhGiaTheoLop(_selMaLop, _selectedNamHoc ?? "");
            var t3 = TruongService.hGetThongKeXepLoaiNangLucTheoLop(_selMaLop, _selectedNamHoc ?? "");
            var t4 = TruongService.hGetThongKeXepLoaiPhamChatTheoLop(_selMaLop, _selectedNamHoc ?? "");
            var t5 = TruongService.hGetKetQuaKhenThuong(
                        lopId: _selLopId > 0 ? _selLopId : (int?)null,
                        namHoc: _selectedNamHoc ?? "");

            await Task.WhenAll(t1, t2, t3, t4, t5);

            _diemList = t1.Result;
            _dgList   = t2.Result;
            _nlList   = t3.Result;
            _pcList   = t4.Result;

            // Tab 6: lấy record đầu tiên (hoặc tạo mới)
            var khenList = t5.Result;
            _khenModel = khenList.FirstOrDefault() ?? new ScnKetQuaKhenThuongDTO
            {
                Id = 0,
                KhoiId = _selKhoiId > 0 ? _selKhoiId : (int?)null,
                LopId  = _selLopId  > 0 ? _selLopId  : (int?)null,
                NamHoc = _selectedNamHoc ?? "",
                NoiDungKhenThuong = ""
            };
            // Reset để OnAfterRenderAsync khởi tạo lại Quill
            _quillInitialized = false;
        }
        catch (Exception ex)
        {
            Console.WriteLine(ex);
            await ShowToast("Da xay ra loi, vui long thu lai!", "toast-err", "error");
        }
        finally { _isLoading = false; StateHasChanged(); }
    }

    private void ClearData()
    {
        _diemList  = new();
        _dgList    = new();
        _nlList    = new();
        _pcList    = new();
        _khenModel = new();
        _quillInitialized = false;
    }

    // ── LƯU KẾT QUẢ KHEN THƯỞNG ──
    private async Task SaveKhenThuong()
    {
        if (_isKhenSaving) return;
        _isKhenSaving = true; StateHasChanged();
        try
        {
            // Lấy nội dung HTML từ Quill
            string html = await JS.InvokeAsync<string>("scnKhen.getContent");

            _khenModel ??= new ScnKetQuaKhenThuongDTO();
            _khenModel.NoiDungKhenThuong = html;
            _khenModel.NamHoc  = _selectedNamHoc ?? "";
            _khenModel.KhoiId  = _selKhoiId > 0 ? _selKhoiId : (int?)null;
            _khenModel.LopId   = _selLopId  > 0 ? _selLopId  : (int?)null;

            await TruongService.hUpsertKetQuaKhenThuong(_khenModel);

            // Nếu là INSERT mới, reload để lấy Id
            if (_khenModel.Id <= 0)
            {
                var list = await TruongService.hGetKetQuaKhenThuong(
                    lopId: _selLopId > 0 ? _selLopId : (int?)null,
                    namHoc: _selectedNamHoc ?? "");
                _khenModel = list.FirstOrDefault() ?? _khenModel;
            }

            await ShowToast("Đã lưu kết quả khen thưởng!", "toast-ok", "check_circle");
        }
        catch (Exception ex)
        {
            Console.WriteLine(ex);
            await ShowToast("Da xay ra loi, vui long thu lai!", "toast-err", "error");
        }
        finally { _isKhenSaving = false; StateHasChanged(); }
    }

    // ── HELPERS ──
    /// <summary>Tra tên môn học từ id_monhoc (dạng string)</summary>
    private string GetTenMonHoc(string? maMonHoc)
    {
        if (string.IsNullOrEmpty(maMonHoc)) return "—";
        var mon = _monHocList.FirstOrDefault(m => m.id_monhoc.ToString() == maMonHoc);
        return mon?.ten_mon_hoc ?? maMonHoc;
    }

    private static string FormatNum(int val) => val == 0 ? "—" : val.ToString();
    private static string FormatPct(decimal val) => val == 0 ? "—" : $"{val:0.##}%";

    private async Task ShowToast(string msg, string css, string icon)
    {
        _toastCts?.Cancel();
        _toastCts  = new System.Threading.CancellationTokenSource();
        _toastMsg  = msg; _toastCss = css; _toastIcon = icon;
        StateHasChanged();
        try { await Task.Delay(3500, _toastCts.Token); _toastMsg = ""; StateHasChanged(); }
        catch (TaskCanceledException) { }
    }

